function Get-RebaseNativeProof($Obligation,[string]$Predecessor,[string]$Result,[string]$OldBase,[datetimeoffset]$Earliest,[datetimeoffset]$Latest,[byte[]]$BranchBytes,[byte[]]$HeadBytes) {
